package com.municipio.base_conocimiento.auditoria.config;
import com.municipio.base_conocimiento.auditoria.service.AuditoriaService;import jakarta.servlet.http.*;import java.security.Principal;import java.util.Set;import org.springframework.stereotype.Component;import org.springframework.web.servlet.HandlerInterceptor;
@Component public class AuditoriaInterceptor implements HandlerInterceptor{private static final Set<String> MUTACIONES=Set.of("POST","PUT","PATCH","DELETE");private final AuditoriaService service;public AuditoriaInterceptor(AuditoriaService service){this.service=service;}@Override public void afterCompletion(HttpServletRequest req,HttpServletResponse res,Object handler,Exception ex){Principal p=req.getUserPrincipal();if(p!=null&&MUTACIONES.contains(req.getMethod())&&!req.getRequestURI().startsWith("/api/auth/refresh"))service.registrar(p.getName(),req.getMethod(),req.getRequestURI(),res.getStatus(),req.getRemoteAddr());}}
